package com.intermarche.backoffice.engine.printing;
import com.google.zxing.*;import com.google.zxing.common.BitMatrix;import com.google.zxing.oned.Code128Writer;import java.nio.charset.StandardCharsets;import java.util.*;
/** The same Code128 pixels drive the software preview and printer payload. User data is never printer code. */
public final class LabelRenderer {
 public record Rendered(String preview,String payload){}
 private LabelRenderer(){}
 public static BitMatrix barcode(String code,int width){if(code==null||!code.matches("[A-Za-z0-9_.:/-]{1,80}"))throw new IllegalArgumentException("Identifiant logistique invalide");return new Code128Writer().encode(code,BarcodeFormat.CODE_128,width,100,Map.of(EncodeHintType.MARGIN,20));}
 private static String xml(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&apos;");}
 private static String hex(String s){var out=new StringBuilder();for(byte b:s.getBytes(StandardCharsets.UTF_8))out.append('_').append(String.format(Locale.ROOT,"%02X",b&255));return out.toString();}
 public static Rendered render(String code,String title,List<String> lines,int width,int height){if(width<400||width>1600||height<350||height>1600||lines.size()>6)throw new IllegalArgumentException("Dimensions ou nombre de lignes invalides");if(title==null||title.length()>60||lines.stream().anyMatch(s->s==null||s.length()>200))throw new IllegalArgumentException("Texte de l’étiquette trop long");var bars=barcode(code,width-80);if(bars.getWidth()>width-80)throw new IllegalArgumentException("Élargissez le modèle pour conserver un code-barres lisible");int y=height-160;var displayed=new ArrayList<String>();int columns=Math.max(20,(width-60)/12);for(var line:lines){String remaining=line;while(remaining.length()>columns){int split=remaining.lastIndexOf(' ',columns);if(split<columns/2)split=columns;displayed.add(remaining.substring(0,split));remaining=remaining.substring(split).stripLeading();}displayed.add(remaining);}var svg=new StringBuilder("<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 "+width+" "+height+"\"><rect width=\"100%\" height=\"100%\" fill=\"white\"/><g fill=\"black\" font-family=\"sans-serif\"><text x=\"30\" y=\"45\" font-size=\"26\">"+xml(title)+"</text>");var zpl=new StringBuilder("^XA^CI28^PW"+width+"^LL"+height+"^FO30,20^A0N,26,26^FH_^FD"+hex(title)+"^FS");int row=0;for(String line:displayed){int baseline=80+row*30;if(baseline>y-20)throw new IllegalArgumentException("Le texte dépasse la place disponible");svg.append("<text x=\"30\" y=\"").append(baseline).append("\" font-size=\"20\">").append(xml(line)).append("</text>");zpl.append("^FO30,").append(baseline-20).append("^A0N,20,20^FH_^FD").append(hex(line)).append("^FS");row++;}
 for(int x=0;x<bars.getWidth();x++)if(bars.get(x,0))svg.append("<rect x=\"").append(40+x).append("\" y=\"").append(y).append("\" width=\"1\" height=\"100\"/>");svg.append("<text x=\"40\" y=\"").append(y+130).append("\" font-size=\"22\">").append(xml(code)).append("</text></g></svg>");
 // Rasterise the exact validated barcode, avoiding a second printer-side interpretation.
 int bytes=(bars.getWidth()+7)/8;zpl.append("^FO40,").append(y).append("^GFA,").append(bytes*100).append(',').append(bytes*100).append(',').append(bytes).append(',');for(int yy=0;yy<100;yy++)for(int bx=0;bx<bytes;bx++){int value=0;for(int bit=0;bit<8;bit++){int x=bx*8+bit;if(x<bars.getWidth()&&bars.get(x,0))value|=128>>bit;}zpl.append(String.format(Locale.ROOT,"%02X",value));}zpl.append("^FS^FO40,").append(y+110).append("^A0N,22,22^FH_^FD").append(hex(code)).append("^FS^XZ");return new Rendered(svg.toString(),zpl.toString());}
}
